  'wooden-wheelbarrow-flower-planter': { name: 'Floreira Madeira Carrinho Mão', closure: 'Aberto', tagline: 'Floreira decorativa madeira forma carrinho mão', intro: 'Uma floreira decorativa madeira em forma de carrinho mão — peça jardim com personalidade. Madeira tratada exterior; sustenta plantas jardim ou flores. Perfeita para entradas casa, pátios ou decoração temporária para casamentos campo.', customization: ["Tamanhos de bancada até escala de chão", "Roda funcional ou decorativa", "Acabamento branqueado, envelhecido ou tingido", "Sobrenome ou nome da fazenda gravado", "Conjunto de floreira triciclo combinando opcional", "Acabamento para interior ou exterior"], useCases: ["Varejo em centros de jardinagem", "Decoração externa", "Aluguer décor casamento", "Presentes de casa estilo campestre", "Peça central para varanda", "Expositor sazonal de fim de ano"], packaging: "Roda e alças embaladas planas para otimizar o transporte, envolvidas em espuma e acondicionadas em caixa master de exportação de 5 camadas." },
  'rustic-tricycle-bicycle-planter': { name: 'Floreira Rústica Triciclo / Bicicleta', closure: 'Aberto', tagline: 'Floreira madeira forma triciclo decorativo', intro: 'Uma floreira em madeira em forma de triciclo clássico ou bicicleta — peça decorativa com personalidade. Vários cestos floreira incorporados no "veículo" madeira. Para varandas, terraços ou jardins que amam personalidade.', customization: ["Estilo triciclo, bicicleta ou carrinho de mão", "Rodas funcionais ou decorativas", "Acabamento envelhecido, pintado ou natural", "Nome da família ou fazenda gravado", "Acabamento para interior ou exterior", "Variantes pintadas para as festas"], useCases: ["Varejo em centros de jardinagem", "Decoração de varanda frontal", "Aluguer décor casamento", "Expositor sazonal de fim de ano", "Presentes para casa de campo", "Varejo de floricultura"], packaging: "Embalado plano para otimizar o transporte, envolvido em espuma e acondicionado em caixa master de exportação de 5 camadas com instruções de montagem." },
  'set-of-3-round-wood-plant-stand-risers': { name: 'Conjunto 3 Suportes Plantas Madeira Redondos', closure: 'Aberto', tagline: 'Conjunto 3 suportes redondos alturas escalonadas', intro: 'Um conjunto de 3 suportes plantas redondos madeira em alturas escalonadas para mostrar plantas em níveis. Cria um display plantas em qualquer divisão. Madeira maciça com acabamento natural; estrutura sólida sustenta plantas grandes.', customization: ["Conjunto de 3 / 5 / 7 suportes", "Redondo, quadrado ou hexagonal", "Pinho, acácia ou nogueira", "Tingido, oleado ou branqueado", "Marca gravada na borda", "Conjuntos de tamanhos sob medida por revendedor"], useCases: ["Varejo de plantas", "Expositor de centro de jardinagem", "Decoração de selva urbana", "Exposição floral", "Alternativa ao suporte para bolos", "Estandes de feiras"], packaging: "Conjuntos encaixados para otimizar o transporte, saco OPP e acondicionados em caixa master de exportação de 5 camadas." },

