  'wooden-jewelry-storage-box': { name: 'Caixa Storage Joalharia Madeira', closure: 'Misto', tagline: 'Caixa storage joalharia madeira com compartimentos', intro: 'Uma caixa storage joalharia madeira com compartimentos forrados veludo para anéis, brincos, colares e pulseiras. Vários níveis com tabuleiros removíveis; espelho opcional na tampa. A peça completa para uma coleção crescente.', customization: ["Madeira: nogueira, bordo, MDF folheado", "Cor da camurça: preto / creme / rosa claro / personalizada", "Configuração dos nichos: pulseira / anel / relógio", "Logotipo em hot stamping na tampa", "Luva externa opcional", "Dimensionado para joias pequenas ou de exposição"], useCases: ["Varejo de joias", "Alianças casamento", "Presentes aniversário", "Lembranças casamento", "Embalagem para programas de presente", "Dropshipping de e-commerce"], packaging: "Cada caixa em saco OPP, acondicionada em caixa interna pronta para varejo e depois caixa master de exportação de 5 camadas." },
  'wooden-essential-oil-storage-box': { name: 'Caixa Storage Óleos Essenciais Madeira', closure: 'Com Dobradiça', tagline: 'Caixa madeira para óleos essenciais', intro: 'Uma caixa madeira especificamente dimensionada para frascos óleos essenciais 5–15 ml. Compartimentos pré-cortados protegem os frascos e da luz UV. Capacidade típica 30–60 frascos; perfeita para aromaterapeutas e herbalistas.', customization: ["Capacidade: 25 / 36 / 50 / 64 garrafas", "Diâmetro do nicho para frascos de 5 / 10 / 15 ml", "Bambu, pinho, nogueira", "Acolchoamento de espuma ou feltro", "Logotipo ou fórmula de mistura de óleos gravada", "Designs em níveis ou de camada única"], useCases: ["Varejo de óleos essenciais", "Profissionais de aromaterapia", "Organização de spa", "Massoterapia", "Kits de presente para revendedores", "Programas de caixas de assinatura"], packaging: "Saco OPP, caixa retail, depois caixa master exportação 5 camadas." },
  'wooden-yarn-storage-box': { name: 'Caixa Storage Lãs Madeira', closure: 'Aberto', tagline: 'Caixa madeira para lãs com saídas', intro: 'Uma caixa madeira para armazenar novelos lã com saídas na tampa que permitem tricotar enquanto a lã permanece limpa e desemaranhada. Solução ideal para tricoteiras e crocheteiras que apreciam ordem e portabilidade.', customization: ["Número de aberturas de alimentação: 2 / 4 / 6", "Bambu, pinho, nogueira", "Canaleta para agulhas opcional", "Frase sobre tricô gravada na tampa", "Fecho magnético ou de gancho", "Dimensionado para meadas, novelos ou bobinas"], useCases: ["Varejo para hobby de tricô", "Presentes de crochê", "Caixas de assinatura para makers", "Oficinas de artes têxteis", "Estoque de loja de artesanato", "Presentes de hobby para as festas"], packaging: "Saco OPP, caixa retail, depois caixa master exportação 5 camadas." },
  '3-tier-bamboo-spice-rack-organizer': { name: 'Especieiro Bambu 3 Pisos', closure: 'Aberto', tagline: 'Especieiro bambu 3 pisos 18 frascos incluídos', intro: 'Um especieiro bambu 3 pisos com 18 frascos vidro e etiquetas incluídos. Pisos escalonados para ver todas as etiquetas dum relance. Perfeito para bancada cozinha ou montagem parede com kit montagem opcional.', customization: ["Prateleiras de 2 / 3 / 4 níveis", "Bambu, pinho, nogueira", "Opção com conjunto de potes de tempero", "Gravação de logotipo personalizado", "De parede ou de bancada", "Área padrão ou extra-larga"], useCases: ["Cozinhas modernas", "Varejo de especiarias", "Kits de presente de culinária", "Lista de casamento", "Kits para aulas de culinária", "Bastidores da cafeteria"], packaging: "Embalagem plana para otimizar o transporte, saco OPP, caixa de varejo e caixa master de exportação de 5 camadas." },
  'smiley-face-bamboo-tissue-box': { name: 'Caixa Lenços Bambu Smiley', closure: 'Aberto', tagline: 'Caixa lenços bambu com cara sorridente', intro: 'Uma caixa lenços bambu com motivo cara sorridente recortado num dos lados. Traz personalidade simpática a qualquer divisão — quarto crianças, sala estar ou consultório. Bambu food-grade, fácil de limpar.', customization: ["Recorte: sorriso / estrela / coração / logotipo", "Bambu, pinho, carvalho", "Tamanho padrão ou de lenços faciais", "Base deslizante ou removível", "Compatível com caixas de lenços cúbicas ou retangulares", "Lixeira combinando opcional"], useCases: ["Varejo de decoração", "Acessório mesinha cabeceira", "Presente escritório", "Amenidades hóspede hotel", "Retail boutique", "Kits de presente de fim de ano"], packaging: "Saco OPP, caixa colorida de varejo e depois caixa master de exportação de 5 camadas." },
  'vintage-pirate-wooden-treasure-chest-box': { name: 'Baú Tesouro Madeira Pirata Vintage', closure: 'Com Dobradiça', tagline: 'Baú tesouro madeira estilo pirata vintage', intro: 'Um baú tesouro madeira look pirata vintage — bandas metálicas, fecho latão envelhecido e tampa abaulada. Ótimo como caixa presente, decoração temática, storage cosplay ou caixa brincar para crianças. Construção sólida suporta uso diário.', customization: ["Baú individual ou conjunto encaixável de 3 peças", "Cadeado com chave opcional", "Acabamento envelhecido, queimado ou pintado", "Gravação personalizada ou placa de caveira pirata", "Interior forrado feltro opcional", "Decoração interna ou bordas seguras para crianças"], useCases: ["Decoração de brinquedoteca", "Adereços de figurino", "Decoração de bar / pub", "Organização de sala de jogos", "Produtos temáticos de varejo", "Kits de presente de fim de ano"], packaging: "Empilhado / encaixado para otimizar o transporte, envolvido em espuma e acondicionado em caixa master de exportação de 5 camadas." },
  'wooden-dress-up-storage-cart': { name: 'Carrinho Storage Madeira Disfarces', closure: 'Misto', tagline: 'Carrinho madeira com rodas para disfarces crianças', intro: 'Um carrinho storage madeira com rodas — projetado para disfarces crianças, acessórios festa ou cosplay. Compartimentos divididos para roupa, chapéus, joias e sapatos. As rodas permitem movimento entre divisões; o formato carrinho torna a organização divertida.', customization: ["Cor pintada (branco / pastel / personalizada)", "Painel de espelho opcional", "Altura da haste suspensa", "Quantidade gavetas: 2 / 3 / 4", "Suporte antiqueda incluído", "Placa nome criança gravada"], useCases: ["Quartos infantis", "Creches", "Retail crianças boutique", "Guarda de figurinos de teatro", "Adereços de estúdio", "Presentes aniversário"], packaging: "Embalado plano, cantoneiras de espuma e caixa master de exportação de 5 camadas com instruções de montagem." },
  'wooden-sofa-armrest-tray': { name: 'Tabuleiro Apoio Braço Sofá Madeira', closure: 'Aberto', tagline: 'Tabuleiro madeira para apoio braço sofá', intro: 'Um tabuleiro madeira projetado para assentar no apoio braço de um sofá — segura caneca, comando, telemóvel e snack enquanto vê filmes. Pequenos compartimentos divididos; a largura base ajustável encaixa na maioria dos sofás standard.', customization: ["Layouts com nichos para copo / controle / celular", "Bambu ou nogueira", "Ajuste para braços de sofá padrão ou extralargos", "Marca gravada na tampa", "Design dobrável ou fixo", "Base antiderrapante opcional"], useCases: ["Acessório de sala de estar", "Home theater", "Presentes para maratonas no sofá", "Amenidade suite hotel", "Varejo de acessórios de tecnologia", "Presentes Dia dos Pais"], packaging: "Saco OPP, caixa colorida de varejo e depois caixa master de exportação de 5 camadas." },
